"""Embed the Web UI assets in each PlatformIO firmware build."""

from pathlib import Path

Import("env")

web_dir = Path(env.subst("$PROJECT_DIR")) / "web"
generated_dir = Path(env.subst("$BUILD_DIR")) / "generated"
header = generated_dir / "web_assets.h"
assets = (
    ("index.html", "kIndex"),
    ("styles.css", "kStyles"),
    ("app.js", "kScript"),
    ("scale.png", "kScaleIcon"),
)

lines = [
    "// Generated by scripts/embed_web.py from files in web/.",
    "#pragma once",
    "#include <Arduino.h>",
    "",
    "namespace web_assets {",
]
for filename, name in assets:
    contents = (web_dir / filename).read_bytes()
    lines.append(f"static const uint8_t {name}[] PROGMEM = {{")
    for offset in range(0, len(contents), 16):
        chunk = contents[offset:offset + 16]
        lines.append("  " + ", ".join(f"0x{byte:02x}" for byte in chunk) + ",")
    lines.append("};")
lines.extend(["}  // namespace web_assets", ""])

generated = "\n".join(lines)
generated_dir.mkdir(parents=True, exist_ok=True)
if not header.exists() or header.read_text(encoding="utf-8") != generated:
    header.write_text(generated, encoding="utf-8")

env.Append(CPPPATH=[str(generated_dir)])
